tool_input.command:
{
  printf '{"vectors": {\n'
  first=1
  while IFS= read -r line; do
    inner=${line#[\'}
    inner=${inner%]}
    id=${inner%%\'*}
    rest=${inner#*\', }
    if [ "$first" -eq 1 ]; then first=0; else printf ',\n'; fi
    printf '  "%s": [%s]' "$id" "$rest"
  done < .tmp/vectors.txt
  printf '\n}}\n'
} > submission/answers.json
cat submission/answers.json

